const allItems = $input.all();
const suites = allItems.map(i => i.json).filter(Boolean);
const totalTests = suites.reduce((acc, s) => acc + (s.total || 0), 0);
const totalPassed = suites.reduce((acc, s) => acc + (s.passed || 0), 0);
const totalFailed = suites.reduce((acc, s) => acc + (s.failed || 0), 0);
const overallStatus = totalFailed === 0 ? 'ALL PASS' : 'FAILURES FOUND';
console.log('\n╔══════════════════════════════════════════════╗');
console.log('║    NERJA AI — FULL SUITE SUMMARY             ║');
console.log('╚══════════════════════════════════════════════╝');
suites.forEach(s => {
  console.log('  ' + (s.status === 'PASS' ? '✅' : '❌') + ' ' + (s.suite || 'Unknown') + ': ' + (s.passed || 0) + '/' + (s.total || 0));
});
console.log('\n  TOTAL: ' + totalPassed + '/' + totalTests + ' passed — ' + overallStatus);
console.log('  Run at: ' + new Date().toISOString());
return [{ json: { runAt: new Date().toISOString(), suites, totalTests, totalPassed, totalFailed, overallStatus } }];

const data = $json;
const failedSuites = data.suites.filter(s => s.status !== 'PASS');
const failedTests = failedSuites.flatMap(s => (s.tests || []).filter(t => !t.passed));
const report = '🚨 NERJA AI TEST FAILURES

' + failedTests.map(t => '• [' + t.id + '] ' + t.name + '
  Expected: ' + t.expected + '
  Got: ' + t.actual).join('

') + '

Run at: ' + data.runAt;
console.log(report);
return [{ json: { ...data, alertLevel: 'CRITICAL', report } }];

